/// `SceneMetrics.AddPlayerEffects(Player)` (SceneMetrics.cs:754)
pub unsafe fn add_player_effects(this: *mut terraria::scene_metrics::SceneMetrics, mut player: Gc<terraria::player::Player>) {
    terraria::scene_metrics::set_perspective_player(this, rt::wbv(player));
    if ((*(*(*player.ptr()).inventory.at(terraria::player::selected_item(player.ptr()))).ptr()).type_ == 148)
    {
        (*this).zone_water_candle = true;
    }
    if ((*(*(*player.ptr()).inventory.at(terraria::player::selected_item(player.ptr()))).ptr()).type_ == 3117)
    {
        (*this).zone_peace_candle = true;
    }
    if ((*(*(*player.ptr()).inventory.at(terraria::player::selected_item(player.ptr()))).ptr()).type_ == 5322)
    {
        (*this).zone_shadow_candle = true;
    }
    if ((*player.ptr()).music_box >= 0)
    {
        terraria::scene_metrics::set_active_music_box(this, (*player.ptr()).music_box);
    }
    if (*player.ptr()).music_box_silence
    {
        terraria::scene_metrics::set_music_box_silence(this, true);
    }
    if (*player.ptr()).happy_fun_torch_time
    {
        (*this).in_torch_god_minigame = true;
    }
}

